 $('mixedBack').onclick=()=>{state.mixed.pop();render()};$('mixedReset').onclick=()=>{state.mixed=[];render()};$('mixedReady').onclick=()=>{if(state.mixed.length===total&&state.mixed.every(x=>x===d)){next(`Juist: ${whole} ${n}/${d} = ${total}/${d}.`);return}const step=errorStep('mixedAmount');if(step===1)wrong(`Bouw eerst ${whole} volledige pizza${whole===1?'':'’s'} van ${d}/${d}, en daarna nog ${n}/${d}.`);else if(step===2){highlight(`[data-mixed-den="${d}"]`);$('mixedEquation').classList.add('learning-highlight');wrong(`Tel per volledige pizza ${d} stukken. Kijk daarna hoeveel stukken nog overblijven.`)}else{highlight(`[data-mixed-den="${d}"]`,true);$('mixedEquation').innerHTML=`${whole} ${fractionHtml(n,d,true)} = ${fractionHtml(total,d,true)}`;wrong(`Je hebt in totaal ${total} stukken van 1/${d} nodig. Bouw ze nog zelf.`)}};render();
