function fractionColor(d){return({1:'#ef554f',2:'#ed6fa5',3:'#f29a38',4:'#f4cf45',5:'#65bd69',6:'#52bdd0',8:'#5687d8',10:'#9a65c7',12:'#7d8795'})[d]||'#55bad8'}
function fractionHtml(n,d,stacked=false){return stacked?`<span class="stacked-frac"><span>${n}</span><span>${d}</span></span>`:`${n}/${d}`}
function labMarkup(dens,left,right,extra=''){const stacked=mode==='equal'||mode==='compare',guides=extra.includes('tower')?'<div class="height-guides" aria-hidden="true"><i class="left-guide"></i><i class="right-guide"></i></div>':'';return `<div class="fraction-lab ${extra}"><aside id="fractionTray" class="fraction-tray">${dens.map(d=>`<div class="unit-tile" data-unit="${d}"><span class="unit-model"><i style="width:${100/d}%;background:${fractionColor(d)}"></i></span><b>${fractionHtml(1,d,stacked)}</b><small>kies</small></div>`).join('')}</aside><div class="bar-zones"><div class="bar-zone" data-zone="left"><b>${left}</b><canvas id="leftBar"></canvas><button class="take-back" type="button">↩ Laatste stuk terug</button></div><div class="bar-zone" data-zone="right"><b>${right}</b><canvas id="rightBar"></canvas><button class="take-back" type="button">↩ Laatste stuk terug</button></div>${guides}</div></div>`}
function setupBarLab(dens,zones){let selected=null;drawLabBars();const place=(zone,den)=>{const list=state[zone.dataset.zone];if(sum(list)+1/den<=1.001){list.push(den);drawLabBars()}};document.querySelectorAll('[data-unit]').forEach(tile=>{tile.onclick=()=>{document.querySelectorAll('[data-unit]').forEach(x=>x.classList.remove('selected'));selected=+tile.dataset.unit;tile.classList.add('selected')};tile.onpointerdown=e=>{tile.setPointerCapture(e.pointerId);tile.classList.add('carrying')};tile.onpointerup=e=>{tile.classList.remove('carrying');const zone=[...document.querySelectorAll('.bar-zone[data-zone]')].find(z=>{const r=z.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom});if(zone)place(zone,+tile.dataset.unit)}});document.querySelectorAll('.bar-zone[data-zone]').forEach(zone=>{zone.onclick=e=>{if(!e.target.closest('.take-back')&&selected)place(zone,selected)};zone.querySelector('.take-back').onclick=e=>{e.stopPropagation();state[zone.dataset.zone].pop();drawLabBars()}})}
function drawLabBars(){if($('leftBar'))drawUnitBar('leftBar',state.left||[]);if($('rightBar'))drawUnitBar('rightBar',state.right||[]);updateTowerGuides();const equation=$('equalEquation');if(equation){const l=sum(state.left||[]),r=sum(state.right||[]);equation.innerHTML=state.left?.length&&state.right?.length&&Math.abs(l-r)<.001?`${representationHtml(state.left)} <b>=</b> ${representationHtml(state.right)}`:'Bouw dezelfde hoeveelheid met twee soorten stukken.'}}
function updateTowerGuides(){const zones=document.querySelector('.tower-lab .bar-zones'),left=$('leftBar'),right=$('rightBar');if(!zones||!left||!right)return;const zr=zones.getBoundingClientRect(),lr=left.getBoundingClientRect(),rr=right.getBoundingClientRect(),leftLine=zones.querySelector('.left-guide'),rightLine=zones.querySelector('.right-guide'),l=sum(state.left||[]),r=sum(state.right||[]),towerTop=(rect,value)=>rect.top-zr.top+((345-330*value)/370)*rect.height;leftLine.style.top=`${towerTop(lr,l)}px`;rightLine.style.top=`${towerTop(rr,r)}px`;leftLine.style.borderColor=state.left?.length?fractionColor(state.left[0]):'';rightLine.style.borderColor=state.right?.length?fractionColor(state.right[0]):'';leftLine.hidden=!state.left?.length;rightLine.hidden=!state.right?.length}
function representationLabel(pieces){return pieces.length&&pieces.every(d=>d===pieces[0])?`${pieces.length}/${pieces[0]}`:pieces.map(d=>`1/${d}`).join(' + ')}
function representationHtml(pieces){return pieces.length&&pieces.every(d=>d===pieces[0])?fractionHtml(pieces.length,pieces[0],true):pieces.map(d=>fractionHtml(1,d,true)).join(' + ')}
function drawCanvasFraction(x,cx,cy,d,stacked){x.fillStyle='#173f62';x.textAlign='center';x.textBaseline='middle';if(!stacked){x.font='bold 18px Arial';x.fillText(`1/${d}`,cx,cy);return}x.font='bold 15px Arial';x.fillText('1',cx,cy-11);x.fillRect(cx-12,cy-1,24,2);x.fillText(String(d),cx,cy+12)}
function drawUnitBar(id,pieces){const c=$(id),x=c.getContext('2d'),tower=!!c.closest('.tower-lab'),stacked=mode==='equal'||mode==='compare';if(tower){c.width=240;c.height=370;x.clearRect(0,0,240,370);x.strokeStyle='#173f62';x.lineWidth=4;x.strokeRect(55,15,130,330);let top=345;for(const d of pieces){const h=330/d;top-=h;x.fillStyle=fractionColor(d);x.fillRect(55,top,130,h);x.strokeStyle='#fff';x.lineWidth=3;x.strokeRect(55,top,130,h);drawCanvasFraction(x,120,top+h/2,d,stacked)}x.strokeStyle='#173f62';x.lineWidth=5;x.beginPath();x.moveTo(25,345);x.lineTo(215,345);x.stroke();return}c.width=800;c.height=100;x.clearRect(0,0,800,100);x.strokeStyle='#173f62';x.lineWidth=4;x.strokeRect(10,15,780,70);let pos=10;for(const d of pieces){const w=780/d;x.fillStyle=fractionColor(d);x.fillRect(pos,15,w,70);x.strokeStyle='#fff';x.lineWidth=3;x.strokeRect(pos,15,w,70);drawCanvasFraction(x,pos+w/2,50,d,stacked);pos+=w}}
function sum(list){return list.reduce((s,d)=>s+1/d,0)}function fractionLabel(v){if(Math.abs(v-1)<.001)return'1 L';if(v>1){const whole=Math.floor(v),part=v-whole;for(const d of [2,4,8]){const n=Math.round(part*d);if(Math.abs(n/d-part)<.001)return`${whole} ${n}/${d} L`}}for(const d of [2,4,8]){const n=Math.round(v*d);if(Math.abs(n/d-v)<.001)return`${n}/${d} L`}return`${v.toFixed(2)} L`}
function draw(id,food,n,d){const c=$(id),x=c.getContext('2d'),s=300;c.width=c.height=s;x.clearRect(0,0,s,s);if(food==='chocolade'){const im=imgs.chocolade;x.drawImage(im,10,55,280,190);const cols=4,rows=3;for(let i=n;i<12;i++){const col=i%cols,row=Math.floor(i/cols);x.fillStyle='#f4fbfd';x.fillRect(10+col*70,55+row*63.4,70,63.4)}return}const im=imgs[food];for(let i=0;i<n;i++){const a=-Math.PI/2+i*Math.PI*2/d,b=-Math.PI/2+(i+1)*Math.PI*2/d;x.save();x.beginPath();x.moveTo(150,150);x.arc(150,150,135,a,b);x.closePath();x.clip();x.drawImage(im,15,15,270,270);x.restore();x.strokeStyle='#fff';x.lineWidth=3;x.stroke()}x.beginPath();x.arc(150,150,135,0,Math.PI*2);x.strokeStyle='#9ab5c0';x.stroke()}
function drawBar(id,n,d,kind){const c=$(id),x=c.getContext('2d');c.width=240;c.height=180;x.clearRect(0,0,240,180);if(kind){const w=190,h=90,X=25,Y=45;for(let i=0;i<d;i++){x.fillStyle=i<n?'#55bad8':'#fff';x.fillRect(X+i*w/d,Y,w/d,h);x.strokeStyle='#173f62';x.strokeRect(X+i*w/d,Y,w/d,h)}}else{for(let i=0;i<n;i++){x.beginPath();x.moveTo(120,90);x.arc(120,90,75,-Math.PI/2+i*2*Math.PI/d,-Math.PI/2+(i+1)*2*Math.PI/d);x.closePath();x.fillStyle='#55bad8';x.fill();x.strokeStyle='#fff';x.stroke()}x.beginPath();x.arc(120,90,75,0,Math.PI*2);x.strokeStyle='#173f62';x.stroke()}}
function bar(n,d){return `<div class="bar">${Array.from({length:d},(_,i)=>`<i class="${i<n?'':'empty'}"></i>`).join('')}</div>`}
